<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '@/api'
import { dateTime } from '@/utils/format'
const loading=ref(false);const result=reactive({items:[],total:0});const params=reactive({status_filter:'',target_type:'',page:1,page_size:20});const dialog=ref(false);const current=ref(null);const handle=reactive({status:'resolved',result:''})
const state={pending:['待处理','warning'],processing:['处理中','primary'],resolved:['已解决','success'],rejected:['已驳回','info']}
const load=async()=>{loading.value=true;try{Object.assign(result,await api.get('/admin/reports',{params}))}finally{loading.value=false}}
const open=(row)=>{current.value=row;handle.status=row.status==='pending'?'processing':'resolved';handle.result=row.result||'';dialog.value=true}
const submit=async()=>{if(!handle.result)return ElMessage.warning('请填写处理结论');await api.patch(`/admin/reports/${current.value.id}`,handle);ElMessage.success('举报已处理');dialog.value=false;load()}
onMounted(load)
</script>
<template><div><div class="risk-summary"><div><span><el-icon><Warning/></el-icon></span><div><strong>{{result.items.filter(i=>i.status==='pending').length}}</strong><p>当前页待处理</p></div></div><div><span><el-icon><Loading/></el-icon></span><div><strong>{{result.items.filter(i=>i.status==='processing').length}}</strong><p>正在跟进</p></div></div><div><span><el-icon><CircleCheck/></el-icon></span><div><strong>{{result.items.filter(i=>i.status==='resolved').length}}</strong><p>已解决</p></div></div><div class="risk-note"><el-icon><InfoFilled/></el-icon> 平台风控响应目标：普通举报 24 小时内处理，高风险举报 2 小时内介入。</div></div><div class="admin-filters"><el-select v-model="params.status_filter" clearable placeholder="处理状态" style="width:150px"><el-option v-for="(item,key) in state" :key="key" :label="item[0]" :value="key"/></el-select><el-select v-model="params.target_type" clearable placeholder="举报类型" style="width:150px"><el-option label="商品" value="product"/><el-option label="用户" value="user"/><el-option label="订单" value="order"/></el-select><el-button type="success" @click="params.page=1;load()">查询</el-button><el-button @click="Object.assign(params,{status_filter:'',target_type:'',page:1});load()">重置</el-button><span class="filter-count">共 {{result.total}} 条举报</span></div><section class="admin-card"><el-table v-loading="loading" :data="result.items"><el-table-column label="举报人" min-width="150"><template #default="{row}">{{row.reporter?.nickname}}<small class="block">@{{row.reporter?.username}}</small></template></el-table-column><el-table-column label="目标"><template #default="{row}"><el-tag type="info">{{{product:'商品',user:'用户',order:'订单'}[row.target_type]}} #{{row.target_id}}</el-tag></template></el-table-column><el-table-column label="举报原因" min-width="150" prop="reason"/><el-table-column label="详细说明" min-width="260" show-overflow-tooltip prop="description"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="state[row.status][1]">{{state[row.status][0]}}</el-tag></template></el-table-column><el-table-column label="举报时间" width="160"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><el-button size="small" :type="row.status==='pending'?'success':'default'" @click="open(row)">{{row.status==='pending'?'立即处理':'查看/更新'}}</el-button></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="params.page" background layout="total,prev,pager,next" :total="result.total" :page-size="params.page_size" @current-change="load"/></div></section><el-dialog v-model="dialog" title="举报处理" width="560px"><template v-if="current"><div class="report-detail"><dl><div><dt>举报目标</dt><dd>{{current.target_type}} #{{current.target_id}}</dd></div><div><dt>举报原因</dt><dd>{{current.reason}}</dd></div><div><dt>详细说明</dt><dd>{{current.description||'未补充'}}</dd></div></dl></div><el-form label-position="top"><el-form-item label="处理状态"><el-radio-group v-model="handle.status"><el-radio-button value="processing">处理中</el-radio-button><el-radio-button value="resolved">已解决</el-radio-button><el-radio-button value="rejected">驳回举报</el-radio-button></el-radio-group></el-form-item><el-form-item label="处理结论"><el-input v-model="handle.result" type="textarea" :rows="4" placeholder="说明核查结果和采取的措施，该内容会通知举报人"/></el-form-item></el-form></template><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="success" @click="submit">保存处理结果</el-button></template></el-dialog></div></template>
<style scoped>.risk-summary{display:grid;grid-template-columns:200px 200px 200px 1fr;gap:15px;margin-bottom:18px}.risk-summary>div{min-height:88px;display:flex;align-items:center;gap:12px;padding:16px;border:1px solid #e0e6e0;border-radius:10px;background:#fff}.risk-summary>div>span{width:42px;height:42px;display:grid;place-items:center;border-radius:11px;background:#edf4ea;color:#2d7a40;font-size:21px}.risk-summary strong{font-size:23px;color:#1e4e30}.risk-summary p{color:#879089;font-size:11px}.risk-summary .risk-note{color:#7c786b;font-size:12px;background:#fffaf1}.filter-count{margin-left:auto;color:#818a84;font-size:12px}.block{display:block;margin-top:4px;color:#949c96;font-size:10px}.report-detail{padding:15px;margin-bottom:18px;border-radius:8px;background:#f5f7f4}.report-detail dl{margin:0}.report-detail dl div{display:flex;margin:7px 0}.report-detail dt{width:85px;color:#8a938c}.report-detail dd{margin:0;color:#39463d}</style>
